3	import { useEffect, useRef, useState } from "react";
4	import styles from "./ShareButton.module.css";
5	
6	interface Props {
7	  title: string;
8	  text?: string;
9	  /** Falls back to window.location.href when omitted. */
10	  url?: string;
11	}
12	
13	/**
14	 * Share / copy-link control. Uses the Web Share API when available
15	 * (mobile, modern browsers) and falls back to copying the URL to the
16	 * clipboard with a brief "Copied" confirmation.
17	 */
18	export default function ShareButton({ title, text, url }: Props) {
19	  const [copied, setCopied] = useState(false);
20	  // Holds the "revert from Copied → Share" timer so we can cancel it
21	  // on unmount. Without this, a user that navigates away before the
22	  // 1800ms elapsed triggers a setState on an unmounted component.
23	  const copiedTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
24	
25	  useEffect(() => {
26	    return () => {
27	      if (copiedTimerRef.current) clearTimeout(copiedTimerRef.current);
28	    };
29	  }, []);
30	
31	  const onShare = async () => {
32	    const href = url ?? (typeof window !== "undefined" ? window.location.href : "");
33	    if (!href) return;
34	
35	    if (typeof navigator !== "undefined" && "share" in navigator) {
36	      try {
37	        await navigator.share({ title, text, url: href });
38	        return;
39	      } catch {
40	        // User aborted or share failed — fall through to copy.
41	      }
42	    }
43	
44	    try {
45	      await navigator.clipboard.writeText(href);
46	      setCopied(true);
47	      // Clear any prior revert in case the user spam-clicked Share.
48	      if (copiedTimerRef.current) clearTimeout(copiedTimerRef.current);
49	      copiedTimerRef.current = setTimeout(() => setCopied(false), 1800);
50	    } catch {
51	      // ignore — clipboard blocked
52	    }
53	  };
54	
55	  return (
56	    <button
57	      type="button"
58	      onClick={() => void onShare()}
59	      className={styles.button}
60	      aria-label="Share this page"
61	    >
62	      <Glyph />
63	      <span>{copied ? "Copied" : "Share"}</span>
64	    </button>
65	  );
66	}
67	
68	function Glyph() {
69	  return (
70	    <svg
71	      className={styles.icon}
72	      viewBox="0 0 24 24"
73	      fill="none"
74	      stroke="currentColor"
75	      strokeWidth="1.75"
76	      strokeLinecap="round"
77	      strokeLinejoin="round"
78	      aria-hidden="true"
79	      suppressHydrationWarning
80	    >
81	      <circle cx="18" cy="5" r="3" />
82	      <circle cx="6" cy="12" r="3" />
83	      <circle cx="18" cy="19" r="3" />
84	      <line x1="8.59" y1="13.51" x2="15.42" y2="17.49" />
85	      <line x1="15.41" y1="6.51" x2="8.59" y2="10.49" />
86	    </svg>
87	  );
88	}
