1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import {
5	  buildShareTargets,
6	  QUOTE_MAX_CHARS,
7	  truncateQuote,
8	  type ShareIconId,
9	  type ShareTarget,
10	} from "@/lib/share";
11	import styles from "./QuoteShare.module.css";
12	
13	interface Props {
14	  /** Title of the work being quoted — used in the attribution line. */
15	  title: string;
16	  /**
17	   * Absolute URL of the page hosting the passage. We do NOT read
18	   * `window.location` ourselves so the caller can supply a canonical
19	   * URL (no `?page=2` querystring noise in shared links).
20	   */
21	  url: string;
22	  /**
23	   * Ref to the element that wraps the readable content. Selections
24	   * outside this element (e.g. site header, footer) are ignored so
25	   * the popover doesn't appear when the user is just selecting a
26	   * heading or a nav label.
27	   */
28	  containerRef: React.RefObject<HTMLElement | null>;
29	}
30	
31	interface SelectionState {
32	  text: string;
33	  truncated: boolean;
34	  /** Selection bounding rect in viewport coordinates. */
35	  rect: DOMRect;
36	}
37	
38	/** Minimum characters in a selection before the popover appears. */
39	const MIN_SELECT_CHARS = 20;
40	
41	/** Debounce after `selectionchange` before the popover renders. */
42	const SELECTION_DEBOUNCE_MS = 220;
43	
44	/** Popover dimensions used for viewport-edge clamping. Wider now
45	 *  that each button carries an icon alongside its label. */
46	const POPOVER_WIDTH = 490;
47	const POPOVER_HEIGHT = 44;
48	const VIEWPORT_PADDING = 12;
49	
50	/**
51	 * Floating share-the-quote popover. Listens for text selections
52	 * inside `containerRef`; when one settles longer than
53	 * `MIN_SELECT_CHARS`, renders a popover anchored above (or below)
54	 * the selection with X / Facebook / Bluesky / Copy buttons.
55	 *
56	 * Selection is ignored when:
57	 * - Empty / collapsed.
58	 * - Shorter than `MIN_SELECT_CHARS` (filters accidental drags).
59	 * - Outside `containerRef` (header, footer, nav, etc.).
60	 *
61	 * Dismissed on Escape, scroll, click outside the popover, or a
62	 * fresh selection landing outside the previous container.
63	 */
64	export default function QuoteShare({ title, url, containerRef }: Props) {
65	  const [selection, setSelection] = useState<SelectionState | null>(null);
66	  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
67	  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
68	  const popoverRef = useRef<HTMLDivElement>(null);
69	
70	  const dismiss = useCallback(() => {
71	    if (debounceRef.current) {
72	      clearTimeout(debounceRef.current);
73	      debounceRef.current = null;
74	    }
75	    setSelection(null);
76	    setCopiedIndex(null);
77	  }, []);
78	
79	  useEffect(() => {
80	    return () => {
81	      if (debounceRef.current) clearTimeout(debounceRef.current);
82	    };
83	  }, []);
84	
85	  // Track selections. selectionchange fires on every cursor move
86	  // during a drag, so we debounce until the user pauses — otherwise
87	  // the popover would chase the cursor.
88	  useEffect(() => {
89	    const onSelectionChange = () => {
90	      if (debounceRef.current) clearTimeout(debounceRef.current);
91	      debounceRef.current = setTimeout(() => {
92	        const container = containerRef.current;
93	        if (!container) {
94	          setSelection(null);
95	          return;
96	        }
97	        const sel = window.getSelection();
98	        if (!sel || sel.isCollapsed || sel.rangeCount === 0) {
99	          setSelection(null);
100	          return;
101	        }
102	        const range = sel.getRangeAt(0);
103	        // Both ends of the selection must be inside the container.
104	        // Without this, dragging from a heading into the body, or
105	        // selecting across the site chrome, would trigger us.
106	        if (
107	          !container.contains(range.startContainer) ||
108	          !container.contains(range.endContainer)
109	        ) {
110	          setSelection(null);
111	          return;
112	        }
113	        const raw = sel.toString().trim();
114	        if (raw.length < MIN_SELECT_CHARS) {
115	          setSelection(null);
116	          return;
117	        }
118	        const { text, truncated } = truncateQuote(raw, QUOTE_MAX_CHARS);
119	        const rect = range.getBoundingClientRect();
120	        setSelection({ text, truncated, rect });
121	      }, SELECTION_DEBOUNCE_MS);
122	    };
123	
124	    document.addEventListener("selectionchange", onSelectionChange);
125	    return () => {
126	      document.removeEventListener("selectionchange", onSelectionChange);
127	    };
128	  }, [containerRef]);
129	
130	  // Dismissal triggers — Escape, scroll, click outside.
131	  useEffect(() => {
132	    if (!selection) return;
133	
134	    const onKey = (e: KeyboardEvent) => {
135	      if (e.key === "Escape") dismiss();
136	    };
137	    const onScroll = () => dismiss();
138	    const onPointerDown = (e: PointerEvent) => {
139	      const target = e.target as Node | null;
140	      if (target && popoverRef.current?.contains(target)) return;
141	      // Wait one tick — if the pointer-down is part of starting a
142	      // new selection, the upcoming `selectionchange` will replace
143	      // our state with the new selection instead of clearing it.
144	      setTimeout(() => {
145	        const sel = window.getSelection();
146	        if (!sel || sel.isCollapsed) dismiss();
147	      }, 0);
148	    };
149	
150	    window.addEventListener("keydown", onKey);
151	    window.addEventListener("scroll", onScroll, { passive: true });
152	    document.addEventListener("pointerdown", onPointerDown);
153	    return () => {
154	      window.removeEventListener("keydown", onKey);
155	      window.removeEventListener("scroll", onScroll);
156	      document.removeEventListener("pointerdown", onPointerDown);
157	    };
158	  }, [selection, dismiss]);
159	
160	  if (!selection) return null;
161	
162	  const position = computePosition(selection.rect);
163	  const targets = buildShareTargets({
164	    text: selection.text,
165	    title,
166	    url,
167	    truncated: selection.truncated,
168	  });
169	
170	  const onShareClick = async (target: ShareTarget, index: number) => {
171	    if (target.action.kind === "url") {
172	      window.open(target.action.url, "_blank", "noopener,noreferrer");
173	      dismiss();
174	      return;
175	    }
176	    try {
177	      await navigator.clipboard.writeText(target.action.payload);
178	      setCopiedIndex(index);
179	      setTimeout(() => setCopiedIndex(null), 1200);
180	    } catch {
181	      // Clipboard write may fail (focus loss, permission). Fail
182	      // silently — the user can re-select and retry. No toast on
183	      // this site by design.
184	    }
185	  };
186	
187	  return (
188	    <div
189	      ref={popoverRef}
190	      className={styles.popover}
191	      role="toolbar"
192	      aria-label="Share selected quote"
193	      style={{
194	        top: `${position.top}px`,
195	        left: `${position.left}px`,
196	        // Block pointer-down propagation so clicking the popover
197	        // doesn't dismiss it via the outside-click handler before
198	        // the click resolves.
199	        pointerEvents: "auto",
200	      }}
201	      onPointerDown={(e) => {
202	        e.stopPropagation();
203	      }}
204	    >
205	      {targets.map((target, i) => {
206	        const isCopy = target.action.kind === "copy";
207	        const showCopied = isCopy && copiedIndex === i;
208	        return (
209	          <button
210	            key={target.label}
211	            type="button"
212	            className={`${styles.button} ${
213	              showCopied ? styles.buttonCopied : ""
214	            }`}
215	            aria-label={SHARE_ARIA[target.icon]}
216	            title={SHARE_ARIA[target.icon]}
217	            onClick={() => void onShareClick(target, i)}
218	          >
219	            {showCopied ? <CheckGlyph /> : <ShareGlyph id={target.icon} />}
220	            <span className={styles.label}>
221	              {showCopied ? "Copied" : target.label}
222	            </span>
223	          </button>
224	        );
225	      })}
226	    </div>
227	  );
228	}
229	
230	/**
231	 * Pick a viewport-clamped {top, left} for the popover relative to
232	 * the selection rect. Prefers above-the-selection; falls below when
233	 * there isn't room (or on a tall selection that runs off the top).
234	 */
235	function computePosition(rect: DOMRect) {
236	  const vw = window.innerWidth;
237	  const vh = window.innerHeight;
238	  const spaceAbove = rect.top;
239	  const spaceBelow = vh - rect.bottom;
240	
241	  // Horizontal: center on the selection, clamped to viewport.
242	  const desiredLeft = rect.left + rect.width / 2 - POPOVER_WIDTH / 2;
243	  const left = Math.max(
244	    VIEWPORT_PADDING,
245	    Math.min(desiredLeft, vw - POPOVER_WIDTH - VIEWPORT_PADDING),
246	  );
247	
248	  // Vertical: above unless there's not enough room — then below.
249	  const above = spaceAbove >= POPOVER_HEIGHT + VIEWPORT_PADDING * 2;
250	  if (above) {
251	    return { top: rect.top - POPOVER_HEIGHT - 8, left };
252	  }
253	  if (spaceBelow >= POPOVER_HEIGHT + VIEWPORT_PADDING * 2) {
254	    return { top: rect.bottom + 8, left };
255	  }
256	  // Tight viewport — pin near the top of the visible area as a
257	  // last resort so the popover is still reachable.
258	  return { top: VIEWPORT_PADDING, left };
259	}
260	
261	/**
262	 * Descriptive accessible names. The visible label collapses to
263	 * icon-only on narrow screens (see `.label` in the CSS module), so
264	 * each button carries the full intent here for screen readers and as
265	 * a hover tooltip — and to disambiguate the X glyph from a close
266	 * button.
267	 */
268	const SHARE_ARIA: Record<ShareIconId, string> = {
269	  x: "Share on X",
270	  facebook: "Share on Facebook",
271	  bluesky: "Share on Bluesky",
272	  copy: "Copy quote and link",
273	  link: "Copy link to this passage",
274	};
275	
276	function ShareGlyph({ id }: { id: ShareIconId }) {
277	  switch (id) {
278	    case "x":
279	      return <XBrandGlyph />;
280	    case "facebook":
281	      return <FacebookGlyph />;
282	    case "bluesky":
283	      return <BlueskyGlyph />;
284	    case "copy":
285	      return <CopyGlyph />;
286	    case "link":
287	      return <LinkGlyph />;
288	  }
289	}
