318	function CopyGlyph() {
319	  return (
320	    <svg className={styles.icon} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" suppressHydrationWarning>
321	      <rect x="9" y="9" width="11" height="11" rx="2" />
322	      <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
323	    </svg>
