1	/* Floating popover anchored to the reader's text selection. */
2	
3	.popover {
4	  position: fixed;
5	  z-index: 90;
6	  display: flex;
7	  align-items: center;
8	  gap: 4px;
9	  padding: 6px;
10	  /* Never let the toolbar run past the viewport edge on small
11	     screens — the buttons stay on one line (labels collapse via the
12	     media query below). */
13	  max-width: calc(100vw - 24px);
14	  background: var(--bg-surface);
15	  border: 1px solid var(--border-line);
16	  border-radius: var(--radius-md-app);
17	  box-shadow: 0 12px 28px -12px rgba(0, 0, 0, 0.65);
18	  font-family: var(--font-ui);
19	  /* Slight pop-in — the popover wants to feel responsive without
20	     stealing attention from the selection. */
21	  animation: quoteShareIn 140ms ease-out;
22	}
23	
24	@keyframes quoteShareIn {
25	  from {
26	    opacity: 0;
27	    transform: translateY(2px) scale(0.98);
28	  }
29	  to {
30	    opacity: 1;
31	    transform: translateY(0) scale(1);
32	  }
33	}
34	
