36	  display: inline-flex;
37	  align-items: center;
38	  gap: 4px;
39	  padding: 5px 10px;
40	  border-radius: var(--radius-pill);
41	  border: 1px solid transparent;
42	  background: transparent;
43	  color: var(--text-muted);
44	  font-family: var(--font-ui);
45	  font-size: 12px;
46	  font-weight: 500;
47	  letter-spacing: var(--tracking-tag);
48	  text-transform: uppercase;
