51	  transition:
52	    color var(--transition-fast),
53	    border-color var(--transition-fast),
54	    background var(--transition-fast);
55	}
56	.button:hover {
57	  color: var(--text);
58	  border-color: var(--border-line-hover);
59	}
60	.button:focus-visible {
61	  outline: 2px solid var(--gold);
62	  outline-offset: 2px;
63	}
64	
