68	  flex-shrink: 0;
69	}
70	
71	.label {
72	  display: inline;
73	}
74	
75	/* Narrow screens: drop to icon-only so five buttons fit on one line
76	   without overflowing. Each button keeps its full meaning via the
77	   aria-label + title set in QuoteShare.tsx. */
78	@media (max-width: 520px) {
79	  .label {
80	    display: none;
81	  }
82	}
83	
84	/* "Copied" flash — the copy buttons swap to this for ~1.2s after
85	   a successful clipboard write so the user sees confirmation
86	   without a separate toast. */
87	.buttonCopied {
88	  color: var(--gold);
89	  border-color: var(--gold);
90	  background: var(--gold-dim);
91	}
92	
93	.divider {
94	  width: 1px;
95	  height: 16px;
96	  background: var(--border-line);
97	  margin: 0 2px;
98	}
99	
100	/* Brief amber flash on the passage when a visitor arrives via a
101	   Text Fragments URL (#:~:text=...) and the polyfill scrolls to
102	   it. Chromium handles its own highlight natively; this is the
103	   Firefox/Safari version. */
104	.fragmentFlash {
105	  animation: fragmentFlash 2400ms ease-out;
106	}
107	
108	@keyframes fragmentFlash {
109	  0%, 30% {
110	    background: var(--gold-dim);
111	    box-shadow: 0 0 0 4px var(--gold-dim);
112	  }
113	  100% {
114	    background: transparent;
115	    box-shadow: 0 0 0 0 transparent;
116	  }
117	}
